import os
import base64
import json
from typing import Any, Dict, Optional

import requests


class Auth0TokenRefresher:
    def __init__(
        self,
        domain: Optional[str] = None,
        client_id: Optional[str] = None,
        client_secret: Optional[str] = None,
        audience: Optional[str] = None,
    ):
        self.domain = domain or os.getenv("AUTH0_DOMAIN")
        self.client_id = client_id or os.getenv("AUTH0_CLIENT_ID")
        self.client_secret = client_secret or os.getenv("AUTH0_CLIENT_SECRET")
        self.audience = audience or os.getenv("AUTH0_AUDIENCE")
        if not self.domain:
            raise ValueError("AUTH0_DOMAIN is required")
        if not self.client_id:
            raise ValueError("AUTH0_CLIENT_ID is required")
        if not self.client_secret:
            raise ValueError("AUTH0_CLIENT_SECRET is required")

    def refresh_session(
        self,
        refresh_token: str,
        scope: str = "openid profile email offline_access",
        timeout: int = 30,
    ) -> Dict[str, Any]:
        url = f"https://{self.domain}/oauth/token"
        payload: Dict[str, Any] = {
            "grant_type": "refresh_token",
            "client_id": self.client_id,
            "client_secret": self.client_secret,
            "refresh_token": refresh_token,
            "scope": scope,
        }
        if self.audience:
            payload["audience"] = self.audience

        resp = requests.post(url, json=payload, timeout=timeout)
        resp.raise_for_status()
        data = resp.json()

        access_token = data.get("access_token")
        expires_in = data.get("expires_in")
        token_type = data.get("token_type")
        new_refresh_token = data.get("refresh_token", refresh_token)

        result = {
            "access_token": access_token,
            "refresh_token": new_refresh_token,
            "token_type": token_type,
            "expires_in": expires_in,
            "raw": data,
        }

        if access_token:
            result["claims"] = self._decode_jwt_without_verification(access_token)

        return result

    @staticmethod
    def _decode_jwt_without_verification(token: str) -> Dict[str, Any]:
        try:
            parts = token.split(".")
            if len(parts) < 2:
                return {}
            payload_b64 = parts[1]
            padding = "=" * (-len(payload_b64) % 4)
            payload = base64.urlsafe_b64decode((payload_b64 + padding).encode("utf-8"))
            return json.loads(payload.decode("utf-8"))
        except Exception:
            return {}


def refresh_expired_session(refresh_token: str) -> Dict[str, Any]:
    return Auth0TokenRefresher().refresh_session(refresh_token)
